/**
 * Convierte una referencia de celda ('A1') en coordenadas {col: 1, row: 1}.
 * @param {string} cellId La referencia de la celda.
 * @returns {{col: number, row: number}} Coordenadas de la columna y la fila (base 1).
 */
function getCoordinates(cellId) {
    const colLetters = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    let column = 0;
    let row = 0;

    for (let i = 0; i < cellId.length; i++) {
        const char = cellId[i].toUpperCase();
        if (!isNaN(parseInt(char))) {
            row = parseInt(char); // Es el número de fila
        } else if (colLetters.includes(char)) {
            // Calcular columna base 0
            column += colLetters.indexOf(char) + 1;
        }
    }
    return { col: column, row: row };
}
