/**
 * Genera un array de coordenadas para todas las celdas dentro de un rango (ej: 'A', 1, 'C', 3).
 * @param {string} startCol Columna inicial.
 * @param {number} startRow Fila inicial.
 * @param {string} endCol Columna final.
 * @param {number} endRow Fila final.
 * @returns {Array<{col: number, row: number}>} Array de coordenadas.
 */
function getRangeCoordinates(startCol, startRow, endCol, endRow) {
    const coords = [];
    let currentColNum = getColIndexFromName(startCol);
    let currentColEnd = getColIndexFromName(endCol);

    while (currentColNum <= currentColEnd && startRow <= endRow) {
        let currentRow = Math.max(1, startRow); // Asegurar que la fila sea al menos 1
        while (currentRow <= endRow) {
            coords.push({ col: currentColNum, row: currentRow });
            currentRow++;
        }
        currentColNum++;
    }
    return coords;
}

/**
 * Convierte una letra de columna ('A') a su índice numérico (1).
 */
function getColIndexFromName(colLetter) {
    const colLetters = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    const index = colLetters.indexOf(colLetter.toUpperCase());
    return index === -1 ? 0 : index + 1;
}
