function getValueFromCell(cellId) {
    const cellElement = document.querySelector(`[data-cell="${cellId}"]`);
    if (!cellElement || !cellElement.contentEditable) return null;

    const textValue = cellElement.innerText.trim();

    // Si la celda contiene una fórmula, queremos evaluar el valor de esa fórmula para obtener su resultado numérico.
    if (textValue.startsWith('=')) {
        try {
