### FUNCION: calculateSum
```javascript
/**
 * Calcula la suma de un rango o celdas separadas por ':' o ';'.
 * @param {string} rangeString Ejemplos: "A1:A3", "B2:C2" o "D4;E5".
 * @returns {number|null} La suma total.
 */
function calculateSum(rangeString) {
    let values = [];
    // Normalizar separadores y dividir en posibles rangos/celdas
    const segments = rangeString.split(/[:;]/).filter(s => s.trim().length > 0);

    for (const segment of segments) {
        if (segment.includes(':')) {
            // Es un rango, ej: A1:A3
            const [startCoord, endCoord] = segment.split(':').map(c => c.toUpperCase());

            let currentCoord = startCoord;
            while (currentCoord && !isNaN(currentCoord[0].charCodeAt(0) - 'A'.charCodeAt(0)) && currentCoord.length <= 2) {
                values.push(getValueFromCell(currentCoord));

                // Mover a la siguiente celda en el mismo rango
                let nextCol = '';
                let nextRow = parseInt(currentCoord.substring(1)) + 1;
                if (currentCoord.length === 2) { // Ej: A3 -> B3
                    nextCol = String.fromCharCode(currentCoord[0].charCodeAt(0) + 1);
                    nextRow = currentCoord[1];
                } else { // Caso de error o manejo simplificado
                     break;
                }
                // Simplificación: solo incrementamos la fila si nos quedamos en el mismo rango de columna.
                // Dado que los rangos son verticales (A1:A3), solo necesitamos incrementar la fila.
                 currentCoord = nextCol + (String(parseInt(currentCoord[1]) + 1)).padStart(1, '0');

            } else {
                // Caso simplificado para rangos columna-por-columna (ej: A1, A2, A3)
                const startRow = parseInt(startCoord.substring(1));
                const endRow = parseInt(endCoord.substring(1));
                for (let i = startRow; i <= endRow; i++) {
                    values.push(getValueFromCell(`${startCoord}${i}`));
                }
            }

        } else {
            // Es una celda suelta, ej: D4
            const value = getValueFromCell(segment.toUpperCase());
            if (value !== null) {
                values.push(value);
            }
        }
    }

    const sum = values.filter(v => v !== null).reduce((acc, val) => acc + val, 0);
    return isNaN(sum) ? null : sum;
}
