         console.log(`Celda ${cellId} vacía.`);
         // Vaciar una celda también requiere recalcular.
         recalculateSheet();
    }
}

/**
 * Inicializa los listeners de eventos en todas las celdas del tablero.
 * Esto garantiza que cualquier interacción con una celda editable sea capturada.
 */
function initializeSheet() {
    // Selecciona todos los <td> que tienen el atributo contenteditable="true"
    const cells = document.querySelectorAll('td[contenteditable="true"]');

    if (cells.length === 0) {
        console.warn("No se encontraron celdas editables en la hoja.");
        return;
    }

    // Adjunta el listener de 'input' y 'blur' a cada celda.
    // Usamos 'input' para cambios mientras tecleas, y 'blur' cuando sales de la celda.
    cells.forEach(cell => {
        // Listener para captura inmediata durante la escritura
        cell.addEventListener('input', handleCellChange); 
        // Listener adicional al salir de la celda (mejor práctica)
        cell.addEventListener('blur', handleCellChange); 
    });

    console.log("Hoja de cálculo inicializada y lista para editar.");
}


/**
 * Función que calcula el valor numérico de una celda basada en su contenido actual o fórmulas circundantes.
 * @param {string} cellId La coordenada de la celda (ej: 'A1').
 * @returns {number|null} El valor numérico o null si no se encuentra/no es un número.
 */
function getValueFromCell(cellId) {
    const cellElement = document.querySelector(`[data-cell="${cellId}"]`);
    if (!cellElement || !cellElement.contentEditable) return null;

    const textValue = cellElement.innerText.trim();

    // Si la celda contiene una fórmula, asumimos que su valor real es el resultado de esa fórmula.
    // Para evitar recursividad infinita o fallos en este entorno sin estado global, 
    // confiamos en que 'recalculateSheet' haya ejecutado los cálculos previamente.
    const number = parseFloat(textValue);
    return isNaN(number) ? null : number;
}

/**
 * Calcula la suma de un rango o celdas separadas por ':' o ';'.
 * @param {string} rangeString Ejemplos: "A1:A3", "B2:C2" o "D4;E5".
 * @returns {number|null} La suma total.
 */
function calculateSum(rangeString) {
    let values = [];
    // Dividimos por rangos (:) y luego por celdas sueltas (;)
    const segments = rangeString.split(/;|\s+/).filter(s => s.trim().length > 0);

    for (const segment of segments) {
        if (!segment.includes(':')) {
            // Celda suelta, ej: D4
            values.push(getValueFromCell(segment.toUpperCase()));
        } else {
            // Rango, ej: A1:A3
            const [startCoord, endCoord] = segment.split(':').map(c => c.trim().toUpperCase());

            if (!startCoord || !endCoord) continue;

            let startRow = parseInt(startCoord.substring(1));
            let endRow = parseInt(endCoord.substring(1));
            const col = startCoord[0]; 

            for (let i = startRow; i <= endRow; i++) {
                values.push(getValueFromCell(`${col}${i}`));
            }
        }
    }

    const sum = values.filter(v => v !== null).reduce((acc, val) => acc + val, 0);
    return isNaN(sum) ? null : sum;
}


/**
 * Recalcula todas las celdas que contienen fórmulas en la hoja.
 */
function recalculateSheet() {
    // Seleccionamos solo las celdas editables para revisar sus fórmulas.
    const formulaCells = document.querySelectorAll('td[contenteditable="true"]');

    formulaCells.forEach(cell => {
        let currentFormula = cell.innerText.trim();

        if (currentFormula.startsWith('=') && !isNaN(parseFloat(currentFormula.substring(1)))) {
            try {
                const formulaContent = currentFormula.substring(1).toUpperCase().trim();
                let resultValue = null;

                // 1. SUMA(range)
                const sumMatch = formulaContent.match(/SUMA\(([^)]+)\)/i);
                if (sumMatch && sumMatch[1]) {
                    resultValue = calculateSum(sumMatch[1]);
                } 
                // 2. Operaciones aritméticas simples: A1-B1, etc.
                else if (/[A-Z0-9]+\s*[-*\/]\s*[A-Z0-9]+/.test(formulaContent)) {
                    let expression = formulaContent;
                    const allCells = document.querySelectorAll('td[contenteditable="true"]');

                    // Reemplazar referencias de celda por sus valores numéricos actuales en el DOM.
                    // Esto es crucial para que la evaluación sea dinámica y use los últimos datos escritos.
                    let evaluatedExpression = expression;
                    allCells.forEach(c => {
                        const cellId = c.getAttribute('data-cell');
                        if (cellId && !c.innerText.startsWith('=')) { // Solo consideramos valores manuales/calculados como fuente
                            const value = parseFloat(c.innerText.trim());
                            if (!isNaN(value) && value !== null) {
                                const regex = new RegExp(`\\b${cellId}\\b`, 'g');
                                evaluatedExpression = evaluatedExpression.replace(regex, value);
                            }
                        }
                    });

                    // Intentar evaluar la expresión resultante (ej: "2-3" en lugar de "A1-B1")
                    resultValue = new Function(`return ${evaluatedExpression}`)();
                }


                // Actualizar el DOM solo si hay un resultado numérico válido
                if (typeof resultValue === 'number' && !isNaN(resultValue) && resultValue !== null) {
                     cell.innerText = resultValue; // Mostrar el valor calculado
                } else if (!isNaN(parseFloat(currentFormula))) {
                    // Si la fórmula no se pudo resolver o es un error, mantenerla visible para debug
                    // Pero si falló en cálculo, dejamos que handleCellChange lo maneje.
                }

            } catch (e) {
                console.error(`Error al recalcular ${cell.getAttribute('data-cell')}:`, e);
                // Si falla el cálculo, mantener la fórmula visible para que el usuario vea el error.
            }
        }
    });
}


