```javascript
/**
 * Intenta evaluar una fórmula en una celda dada, asumiendo un formato simple de suma (A+B).
 * Actualiza el texto interno de la celda con el resultado numérico si tiene éxito.
 * @param {HTMLElement} cellElement El elemento <td> que contiene la fórmula.
 * @returns {boolean} True si la celda fue recalculada, False en caso contrario.
 */
function calculateCell(cellElement) {
    const formulaValue = cellElement.innerText.trim();

    // Verificar si el contenido comienza con '=' y es un texto (no vacío).
    if (!formulaValue || !formulaValue.startsWith('=')) {
        return false; 
    }

    // Eliminar el signo '=' para obtener la fórmula pura
    const formula = formulaValue.substring(1); 

    try {
        // Asumimos que las fórmulas son de la forma: =DEP_ID1+DEP_ID2
        const parts = formula.split('+').map(p => p.trim());
        if (parts.length !== 2) {
             // Si el formato es complejo o diferente, lo dejamos como texto por ahora.
             return false; 
        }

        const [dep1Id, dep2Id] = parts;

        // Buscar los elementos de dependencia usando data-cell
        const dep1Element = document.querySelector(`td[data-cell="${dep1Id}"]`);
        const dep2Element = document.querySelector(`td[data-cell="${dep2Id}"]`);

        if (!dep1Element || !dep2Element) {
             // Si no se encuentran las dependencias, no calculamos nada y mantenemos el texto de la fórmula.
             return false; 
        }

        // Leer los valores actuales de las dependencias (sean números o resultados calculados).
        const val1 = parseFloat(dep1Element.innerText);
        const val2 = parseFloat(dep2Element.innerText);

        if (isNaN(val1) || isNaN(val2)) {
            return false; // Dependencias no numéricas, mantenemos la fórmula como texto.
        }

        // Realizar el cálculo
        const result = val1 + val2;

        // Actualizar el contenido de la celda: Mostrar solo el número (resultado), no la fórmula.
        cellElement.innerText = result; 

        return true; // Éxito en el cálculo
    } catch (e) {
        console.error("Error durante el cálculo:", e);
        // Si falla, mantenemos el texto original de la fórmula.
        return false;
    }
}

/**
 * Itera sobre todas las celdas y recalcula aquellas que contienen fórmulas, 
 * si alguna celda cambia, se debe llamar a esta función para actualizar los resultados dependientes.
 */
function triggerRecalculation() {
    // Selecciona todas las celdas editables del tablero
    const cells = document.querySelectorAll('td[contenteditable="true"]');

    let changesMade = false;

    cells.forEach(cell => {
        // Solo intentamos calcular si el contenido comienza con '=' 
        if (cell.innerText && cell.innerText.trim().startsWith('=')) {
            const success = calculateCell(cell);
            if (success) {
                changesMade = true;
            }
        }
    });

    // console.log("Recálculo de la hoja completado."); // Desactivar logs en producción
}
