/**
 * Recalcula todas las fórmulas de la hoja basándose en los valores actuales de las celdas.
 */
function calculateSheet() {
    // Selecciona todos los elementos que contienen contenido y podrían ser fórmulas
    const cells = document.querySelectorAll('td[contenteditable="true"]');

    let updatedCount = 0;

    cells.forEach(cell => {
        let content = cell.innerText.trim();
        if (!content.startsWith('=')) return; // Solo procesar si es una fórmula

        let formulaString = content;

        // 1. Sustituir referencias de celda (ej: B1) por sus valores actuales.
        // Este regex captura coordenadas como 'A1', 'B12', etc., y los reemplaza con su valor numérico real.
        formulaString = formulaString.replace(/([A-Z]+)(\d+)/g, (match, col, row) => {
            // Intentamos encontrar el elemento de la celda dependiente usando un patrón simple o data attributes.
            // Dado que no tenemos datos de coordenadas mapeados, buscamos el valor en cualquier otra celda editable 
            // cuyo contenido coincida con las referencias conocidas (A1, B1, etc.).
            let dependencyValue = null;

            const allCells = document.querySelectorAll('td[contenteditable="true"]');
            for (const depCell of allCells) {
                let depText = depCell.innerText.trim();
                if (!depText.startsWith('=') && depText !== "") {
                    // Si el texto es numérico y coincide con la referencia, usamos ese valor.
                    try {
                        const numericDepValue = parseFloat(depText);
                        if (!isNaN(numericDepValue) && String(numericDepValue) === match.toUpperCase()) {
                             dependencyValue = numericDepValue;
                            break; 
                        }
                    } catch (e) { /* ignore */ }
                } else if (depText.startsWith('=') && depText.includes(match)) {
                     // Si la dependencia está en una fórmula, esto es demasiado complejo para el alcance actual.
                     dependencyValue = parseFloat(depCell.innerText); // Intentar usar el resultado calculado de la fórmula dependiente.
                     break;
                }
            }

            if (dependencyValue !== null) {
                return dependencyValue;
            }
            // Si no se pudo resolver, mantener el texto original para evitar romper la fórmula si es un error lógico.
            return match; 
        });

        let result;
        try {
            // Evaluar la cadena de la fórmula sustituida (ej: "4+3")
            result = eval(formulaString);
        } catch (e) {
            console.error("Error al evaluar la fórmula:", formulaString, e);
            return; // No actualizar si falla
        }

        // 2. Actualizar el contenido de la celda si el resultado es numérico y diferente del valor actual.
        if (!isNaN(result)) {
            const currentValue = parseFloat(cell.innerText) || 0;
            // Solo actualizar si hay un cambio significativo (para evitar loops infinitos o reescritura innecesaria).
             if (Math.abs(parseFloat(cell.innerText) - result) > 0.001 && cell.innerText !== String(result)) {
                cell.innerText = result;
                updatedCount++;
            }
        }
    });
    return updatedCount;
}
