### FUNCION: handleCellClick
```javascript
function handleCellClick(event) {
    const cell = event.target;
    // 1. Deseleccionar la celda anterior
    if (activeCell && activeCell !== cell) {
        activeCell.style.backgroundColor = ''; // Limpiar color de fondo
    }

    // 2. Seleccionar y activar la nueva celda
    activeCell = cell;
    activeCell.focus(); // Poner foco en la celda (UX mejorada)

    // 3. Forzar que el evento 'blur' se dispare, para actualizar cualquier estado
    // Esto es útil si el click ocurre sobre una celda ya editada o seleccionada.
    setTimeout(() => {
        activeCell.dispatchEvent(new Event('click')); // Disparar un clic simulado (si fuera necesario)
        activeCell.dispatchEvent(new Event('focus')); 
    }, 10);

    // Nota: El evento de coloración se maneja por el listener del panel, pero necesitamos establecer la celda activa aquí.
}
