```javascript
/**
 * Configura los listeners en la cabecera de columnas (col-header) 
 * para mostrar un menú contextual al hacer clic derecho, permitiendo acciones por columna.
 */
function setupColumnSelectionControls() {
    const container = document.getElementById('spreadsheet-container');
    const menu = document.getElementById('column-context-menu');

    if (!container || !menu) return;

    // 1. Listener de clic derecho para mostrar el menú contextual (R6)
    container.addEventListener('contextmenu', function(e) {
        // Solo procesar si el objetivo es un encabezado de columna
        const targetHeader = e.target.closest('.col-header');
        if (!targetHeader || e.button !== 2) return; // Asegura que sea clic derecho

        e.preventDefault(); // Previene el menú contextual nativo del navegador

        // Obtener la letra y el índice de la columna seleccionada
        const colLetter = targetHeader.getAttribute('data-col-letter');
        const colIndex = parseInt(targetHeader.getAttribute('data-col-index'));

        if (!colLetter || isNaN(colIndex)) {
            console.error("No se pudo identificar la columna.");
            return;
        }

        // Mostrar el menú y posicionarlo donde ocurrió el evento
        menu.style.display = 'block';
        menu.style.left = `${e.clientX + 15}px`;
        menu.style.top = `${e.clientY + 10}px`;

        // Almacenar temporalmente la información de la columna activa en el menú (o en un estado global)
        menu.dataset.activeColLetter = colLetter;
        menu.dataset.activeColIndex = colIndex;
    });

    // 2. Listener para hacer clic fuera del contenedor o sobre cualquier elemento no deseado para ocultar el menú
    document.addEventListener('click', function(e) {
        if (!e.target.closest('#column-context-menu')) {
            menu.style.display = 'none';
            // Deseleccionar visualmente la columna si estaba activa
            document.querySelectorAll('.col-header').forEach(th => th.classList.remove('selected-column'));
        }
    });

    // 3. Listener para los botones de acción dentro del menú contextual
    menu.querySelector('[data-action="color"]').addEventListener('click', function() {
        const colLetter = menu.dataset.activeColLetter;
        if (colLetter) {
            showColorPicker();
        }
    });

    menu.querySelector('[data-action="clear"]').addEventListener('click', function() {
        const colLetter = menu.dataset.activeColLetter;
        if (colLetter) {
            clearColumnContent(colLetter);
        }
    });
}

/**
 * Muestra el selector de color y aplica el fondo a la columna seleccionada.
 */
function showColorPicker() {
    const menu = document.getElementById('column-context-menu');
    const colLetter = menu.dataset.activeColLetter;
    const picker = document.getElementById('color-picker');

    if (!colLetter) return;

    // Inicializar el color del selector con cualquier fondo activo (o blanco por defecto)
    let currentColor = '#ffffff'; 
    // Esto requeriría lógica más compleja para obtener el color actual de la columna, 
    // pero por simplicidad asumimos que se pasa un valor inicial o se usa el picker.

    picker.value = currentColor; // Establece el valor inicial del selector

    document.getElementById('spreadsheet-container').querySelector('#color-picker').focus();
}

/**
 * Aplica un color de fondo a todas las celdas de la columna dada.
 * @param {string} colLetter La letra de la columna (A, B, C...).
 */
function applyBackgroundColor(colLetter) {
    const cells = document.querySelectorAll(`td[contenteditable="true"]`);
    let count = 0;

    cells.forEach(cell => {
        // Solo afecta a las celdas que pertenecen a la columna objetivo
        if (cell.getAttribute('data-cell')?.startsWith(colLetter)) {
            const newColor = document.getElementById('color-picker').value;
            cell.style.backgroundColor = newColor;
            count++;
        }
    });

    alert(`Se aplicó el color ${document.getElementById('color-picker').value} a ${count} celdas de la columna ${colLetter}.`);
}

/**
 * Borra completamente el contenido y restablece el fondo de una columna.
 * @param {string} colLetter La letra de la columna (A, B, C...).
 */
function clearColumnContent(colLetter) {
    const cells = document.querySelectorAll(`td[contenteditable="true"]`);
    let count = 0;

    cells.forEach(cell => {
        if (cell.getAttribute('data-cell')?.startsWith(colLetter)) {
            cell.innerText = ''; // Borra el texto visible
            cell.innerHTML = ''; // Asegura que cualquier contenido HTML interno también se borre
            cell.style.backgroundColor = ''; // Restablecer fondo
            count++;
        }
    });

    alert(`Columna ${colLetter} vaciada y restablecida exitosamente: ${count} celdas limpiadas.`);
}
