### script.js
```javascript
// Estado global para rastrear la columna seleccionada (letra y índice)
let selectedColumnLetter = null;
let selectedColumnIndex = -1;

/**
 * R1: Maneja el evento de cambio en las celdas editables.
 * Cuando un usuario escribe o pega contenido, esta función captura el valor 
 * y lo registra (simulando que se actualiza algún estado global).
 * @param {Event} event El evento de cambio ocurrido en el elemento.
 */
function handleCellChange(event) {
    const cell = event.target;
    const cellId = cell.getAttribute('data-cell');
    // Usamos innerText para obtener el texto limpio, ya que contenteditable puede contener HTML
    const newValue = cell.innerText.trim();

    if (cellId && newValue !== "") {
        console.log(`Celda ${cellId} actualizada: "${newValue}"`);
        // Aquí iría la lógica real para guardar o procesar el valor en un sistema de estado.
    } else if (cellId && newValue === "") {
         console.log(`Celda ${cellId} vacía.`);
    }
}

/**
 * Inicializa los listeners de eventos en todas las celdas del tablero y controles de columna.
 */
function initializeSheet() {
    // 1. Listener para celdas editables (R1)
    const cells = document.querySelectorAll('td[contenteditable="true"]');

    if (cells.length === 0) {
        console.warn("No se encontraron celdas editables en la hoja.");
        return;
    }

    cells.forEach(cell => {
        // Listener para captura inmediata durante la escritura
        cell.addEventListener('input', handleCellChange); 
        // Listener adicional al salir de la celda (mejor práctica)
        cell.addEventListener('blur', handleCellChange); 
    });

    console.log("Hoja de cálculo inicializada y lista para editar.");

    // 2. Inicializar controles de columna (R6)
    initializeColumnControls();
}


/**
 * Función principal que arranca la aplicación.
 */
function startApp() {
    // Se llama a la función de inicialización del tablero, incluyendo ahora los controles de columna.
    initializeSheet();
}

// --- Llamada de inicio de la aplicación ---
window.onload = startApp;


/**
 * Aplica un color de fondo a todas las celdas de una columna específica.
 * @param {string} colLetter Letra de la columna (A, B, etc.).
 * @param {string} color Código hexadecimal del color (#RRGGBB).
 */
function applyColumnColor(colLetter, color) {
    const columnCells = getColumnCells(colLetter);

    if (!columnCells || columnCells.length === 0) {
        console.warn(`No se encontraron celdas para la columna ${colLetter}.`);
        return;
    }

    // Limpiar el color de todas las celdas antes de aplicar el nuevo color (para evitar acumulación)
    columnCells.forEach(cell => {
        cell.style.backgroundColor = ''; 
    });

    // Aplicar el nuevo color a la columna seleccionada
    columnCells.forEach(cell => {
        cell.style.backgroundColor = color;
    });

    console.log(`Color de fondo aplicado exitosamente a la columna ${colLetter}: ${color}`);
}

/**
 * Obtiene una lista de todas las celdas (td) que pertenecen a una columna dada.
 * @param {string} colLetter Letra de la columna.
 * @returns {NodeListOf<HTMLElement>|null} Lista de elementos TD o null si no se encuentra nada.
 */
function getColumnCells(colLetter) {
    const columnCells = [];
    // Seleccionar todas las filas del cuerpo (tbody)
    const bodyRows = document.querySelector('tbody')?.querySelectorAll('tr');
    if (!bodyRows || bodyRows.length === 0) return null;

    // Calcular el índice basado en la letra ('A' -> 0, 'B' -> 1, etc.)
    const colIndex = colLetter.charCodeAt(0) - 'A'.charCodeAt(0);

    if (colIndex < 0) return null; // Letra inválida

    bodyRows.forEach(row => {
        // Seleccionar todas las celdas de datos en esta fila
        const cellsInRow = row.querySelectorAll('td[contenteditable="true"]');

        // Verificar si el índice existe dentro de las celdas encontradas en la fila
        if (colIndex >= 0 && colIndex < cellsInRow.length) {
            columnCells.push(cellsInRow[colIndex]);
        } else {
             console.warn(`Fallo al encontrar celda para columna ${colLetter} en esta fila.`);
        }
    });

    return columnCells;
}


/**
 * Inicializa los listeners de eventos para la gestión de columnas (selección, borrar/limpiar).
 * Asigna un manejador a cada letra de cabecera (la segunda fila de thead).
 */
function initializeColumnControls() {
    // 1. Listener para seleccionar columna haciendo clic en su etiqueta (A, B, C...)
    const colLetterHeaders = document.querySelectorAll('.col-header[data-row-label]');

    if (colLetterHeaders.length === 0) return;

    colLetterHeaders.forEach(header => {
        header.addEventListener('click', function() {
            const letter = this.getAttribute('data-col-letter');
            if (!letter) return;

            // Deseleccionar columna anterior y limpiar estilos
            document.querySelectorAll('.selected-column').forEach(el => el.classList.remove('selected-column'));

            // Seleccionar nueva columna y aplicar estilo
            this.parentNode.querySelector('th[data-col-letter="' + letter + '"]').closest('tr').querySelector(`th[data-row-label="${letter}"]`).classList.add('selected-column');

            // Actualizar estado global de la columna seleccionada
            setSelectedColumn(letter);
        });
    });


    // 2. Asignar manejadores a los botones del panel de control (usando event delegation en el contenedor)
    const controlsContainer = document.getElementById('column-controls');

    if (!controlsContainer) return;

    // Manejador para el botón "Borrar Columna" (Usamos el mismo botón que ya existía, pero lo gestionamos vía JS)
    document.querySelectorAll('.delete-column-btn').forEach(button => {
        button.addEventListener('click', function(e) {
            e.stopPropagation(); 

            const colHeader = this.closest('.col-header');
            if (!colHeader) return;

            // Usamos la lógica existente de borrado, pero asegurándonos de que el estado se maneje correctamente
             handleDeleteColumn(colHeader);
        });
    });


    // 3. Manejador para Color (Nuevo)
    document.getElementById('apply-color-btn')?.addEventListener('click', () => {
        if (selectedColumnLetter) {
            const color = document.getElementById('color-picker').value;
            applyColumnColor(selectedColumnLetter, color);
        }
    });

    // 4. Manejador para Vaciar Contenido (Nuevo/Mejorado)
    document.getElementById('clear-column-content-btn')?.addEventListener('click', () => {
        if (selectedColumnLetter) {
            const columnCells = getColumnCells(selectedColumnLetter);
            if (columnCells && columnCells.length > 0) {
                columnCells.forEach(cell => {
                    // Limpiamos texto y contenido HTML para asegurar una limpieza total
                    cell.innerText = ''; 
                    cell.innerHTML = ''; 
                });
                console.log(`Contenido de la columna ${selectedColumnLetter} vaciado exitosamente.`);
            } else {
                alert("No se pudo encontrar ninguna celda en esta columna.");
            }
        }
    });

    // Manejador para Borrar Columna (Renombrado y refactorizado)
    document.getElementById('delete-column-header-btn')?.addEventListener('click', () => {
        if (selectedColumnLetter) {
             handleDeleteColumn(null, selectedColumnLetter);
        }
    });
}


/**
 * Lógica para manejar la eliminación de una columna completa.
 * @param {HTMLElement|null} colHeader El header original o null si se llama desde el botón del panel.
 * @param {string|null} colLetter La letra de la columna a borrar.
 */
function handleDeleteColumn(colHeader, colLetter) {
    if (!colLetter) return;

    const colIndex = parseInt(colHeader?.getAttribute('data-col-index'));
    const columnIndex = colLetter.charCodeAt(0) - 'A'.charCodeAt(0);

    // 1. Eliminar el botón y la etiqueta de columna del thead superior (si existe)
    const headerRow = document.querySelector('.thead > tr');
    if (colHeader) {
        colHeader.remove();
    } else {
        // Si viene del panel, necesitamos encontrarlo por índice o letra en el primer set de headers
        const targetColElement = headerRow.querySelectorAll('.col-header').filter(el => 
            el.getAttribute('data-col-letter') === colLetter
        );
        if (targetColElement.length > 0) {
             targetColElement[0].remove();
        }
    }

    // 2. Eliminar la letra del thead inferior (la etiqueta A, B, C...)
    const letterLabel = document.querySelector('.thead > tr:last-child .col-header[data-row-label="' + colLetter + '"]');
    if (letterLabel) {
        letterLabel.remove();
    }

    // 3. Eliminar las celdas del tbody por índice de columna
    const body = document.querySelector('tbody');
    if (!body) return;

    Array.from(body.querySelectorAll('tr')).forEach(row => {
        // Eliminamos la celda en el índice calculado
        const cells = row.querySelectorAll('td[contenteditable="true"]');
        if (cells.length > columnIndex && colIndex >= 0) {
            cells[columnIndex].remove();
        }
    });

    console.log(`Columna ${colLetter} eliminada completamente.`);
    // Limpiar selección y controles
    setSelectedColumn(null);
}

