function handleColumnAction(event, colLetter) {
    // Prevenir que la acción se dispare si el click es en un botón interno (como el de borrar) o no hay columna seleccionada.
    if (!colLetter || event.target.closest('.delete-column-btn')) {
        return;
    }

    const colHeader = event.currentTarget;
    let selectedColumn = colLetter;

    // 1. Deseleccionar todas las columnas y limpiar estilos previos
    document.querySelectorAll('.col-header[data-col-letter]').forEach(h => {
        h.style.backgroundColor = '';
        h.querySelector('.r6-icon').innerHTML = '&#9660;'; // Reset arrow
        h.querySelector('.r6-icon').style.display = 'none';
    });

    // 2. Seleccionar la columna actual y aplicar estilos/estado
    colHeader.style.backgroundColor = '#cce5ff'; // Color de selección claro
    const iconElement = colHeader.querySelector('.r6-icon');
    if (iconElement) {
        iconElement.innerHTML = '&#9660;'; // Flecha hacia abajo para indicar menú activo/seleccionado
        iconElement.style.display = '';
    }

    // 3. Mostrar o gestionar controles de acción (simulado por un mensaje en la consola)
    console.log(`--- Columna ${selectedColumn} seleccionada ---`);
    console.warn("Acciones disponibles para columna " + selectedColumn + ":");
    console.log("- Borrar Columna: Haga clic en el botón &times; junto a la letra.");
    console.log("- Limpiar Contenido: Ejecutar limpiarColumna('${selectedColumn}')");
    console.log("- Cambiar Color: Ejecutar setColorColumna('${selectedColumn}', '#RRGGBB')");
}

/**
 * Aplica un color de fondo específico a todas las celdas de una columna dada.
 * @param {string} colLetter La letra de la columna (A, B, C...).
 * @param {string} hexColor El código hexadecimal del color (#RRGGBB).
 */
function setColorColumna(colLetter, hexColor) {
    const body = document.querySelector('tbody');
    if (!body) return;

    // Calcular el índice numérico de la columna (A=0, B=1...)
    const colIndex = colLetter.toUpperCase().charCodeAt(0) - 'A'.charCodeAt(0);

    // Seleccionar todas las celdas del cuerpo que corresponden a este índice
    const columnCells = body.querySelectorAll('td');
    if (colIndex < 0 || colIndex >= columnCells.length) {
        console.error(`Columna ${colLetter} no encontrada.`);
        return;
    }

    // Recorrer las celdas y aplicar el estilo de fondo
    columnCells.forEach(cell => {
        if (cell.getAttribute('data-cell')?.toUpperCase().startsWith(colLetter + '')) {
            cell.style.backgroundColor = hexColor;
        }
    });

    console.log(`Columna ${colLetter} coloreada con éxito: ${hexColor}`);
}


/**
 * Borra el contenido de todas las celdas de una columna dada.
 * @param {string} colLetter La letra de la columna (A, B, C...).
 */
function limpiarColumna(colLetter) {
    const body = document.querySelector('tbody');
    if (!body) return;

    // Calcular el índice numérico de la columna (A=0, B=1...)
    const colIndex = colLetter.toUpperCase().charCodeAt(0) - 'A'.charCodeAt(0);

    // Seleccionar todas las celdas del cuerpo que corresponden a este índice
    const columnCells = body.querySelectorAll('td');
    if (colIndex < 0 || colIndex >= columnCells.length) {
        console.error(`Columna ${colLetter} no encontrada.`);
        return;
    }

    // Recorrer las celdas y limpiar contenido
    let clearedCount = 0;
    columnCells.forEach(cell => {
        if (cell.getAttribute('data-cell')?.toUpperCase().startsWith(colLetter + '')) {
            cell.innerText = ''; // Borra el texto visible
            cell.innerHTML = ''; // Asegura que cualquier contenido HTML interno también se borre
            clearedCount++;
        }
    });

    console.log(`Columna ${colLetter} vaciada exitosamente: ${clearedCount} celdas limpiadas.`);
}
