```js
function initializeRowSelection() {
    // Selecciona todos los encabezados de número de fila con la clase row-number-header
    const rowNumberHeaders = document.querySelectorAll('.row-number-header');

    if (rowNumberHeaders.length === 0) {
        console.warn("No se encontraron cabeceras de número de fila con la clase '.row-number-header'.");
        return;
    }

    // Manejador común para acciones de la fila
    const rowActionHandler = function(e) {
        // Previene que el click en los botones internos dispare otros eventos
        if (e.target.tagName === 'BUTTON' || e.target.closest('.row-controls')) {
            return; 
        }

        const headerElement = this;
        const rowNumber = headerElement.getAttribute('data-row-number');
        if (!rowNumber) return;

        console.log(`Fila ${rowNumber} seleccionada.`);

        // 1. Encontrar la fila completa (<tr class="row-container">) que contiene este encabezado de número
        const row = this.closest('.row-container');
        if (!row) {
            console.error("No se pudo encontrar la fila contenedora.");
            return;
        }

        // 2. Limpiar el contenido (funcionalidad original mantenida)
        let cellsToClear = row.querySelectorAll('td[contenteditable="true"]');
        if (cellsToClear.length > 0) {
            let clearedCount = 0;
            cellsToClear.forEach(cell => {
                cell.innerText = ''; // Limpiar texto visible
                cell.innerHTML = ''; // Asegurar limpieza de HTML interno
                clearedCount++;
            });
            console.log(`Fila ${rowNumber} limpiada exitosamente: ${clearedCount} celdas vaciadas.`);
        }


        // 3. Marcar la fila como seleccionada (opcional, pero útil para UI)
        // Aquí se podría añadir una clase de selección si fuera necesario.
    };

    rowNumberHeaders.forEach(header => {
        // Listener para seleccionar/limpiar al hacer clic en el área principal del número
        header.addEventListener('click', rowActionHandler);
    });


    // Inicializar listeners para botones de color y borrado (R7)
    document.querySelectorAll('.color-bg-btn').forEach(button => {
        button.addEventListener('click', function(e) {
            e.stopPropagation(); // Detener propagación para no disparar el click general de la fila
            const headerElement = this.closest('.row-number-header');
            if (!headerElement) return;

            const rowNumber = headerElement.getAttribute('data-row-number');
            console.log(`Intentando colorear fondo de la fila ${rowNumber}.`);

            // Encontrar el contenedor de la fila completa
            const row = headerElement.closest('.row-container');
            if (!row) return;

            // Seleccionar todas las celdas de datos (td[contenteditable="true"]) en esa fila
            const cellsToColor = row.querySelectorAll('td[contenteditable="true"]');

            // Aplicar el color deseado (ejemplo: rojo #ff0000)
            cellsToColor.forEach(cell => {
                cell.style.backgroundColor = '#ff0000'; 
            });

            console.log(`Fondo de la fila ${rowNumber} cambiado a rojo.`);
        });
    });


    document.querySelectorAll('.delete-row-btn').forEach(button => {
        button.addEventListener('click', function(e) {
            e.stopPropagation(); // Detener propagación para no disparar el click general de la fila

            const headerElement = this.closest('.row-number-header');
            if (!headerElement) return;

            const rowNumber = headerElement.getAttribute('data-row-number');
            console.warn(`Intentando borrar la fila ${rowNumber}.`);

            // Encontrar el contenedor de la fila completa
            const row = headerElement.closest('.row-container');
            if (!row) return;

            // Confirmación y eliminación del elemento del DOM
            if (confirm(`¿Está seguro que desea eliminar toda la Fila ${rowNumber}? Esta acción no se puede deshacer.`)) {
                row.remove();
                console.log(`Fila ${rowNumber} eliminada con éxito.`);
            }
        });
    });
}
