/**
 * Borra programáticamente todo el contenido de todas las celdas de una fila seleccionada.
 * @param {HTMLElement} row El elemento TR de la fila a limpiar.
 */
function clearRowContent(row) {
    const cells = row.querySelectorAll('th, td');

    let clearedCount = 0;
    cells.forEach(cell => {
        // Limpiamos el contenido y también el estilo de fondo para restaurar la apariencia base.
        cell.innerText = '';
        cell.innerHTML = '';
        cell.style.backgroundColor = ''; // Eliminar color de fondo aplicado por selección
        clearedCount++;
    });

    console.log(`Contenido de la fila limpiado exitosamente: ${clearedCount} celdas vaciadas.`);
}
