```javascript
/**
 * Maneja la selección de una fila y actualiza los controles UI.
 * @param {HTMLElement} rowElement La fila (<tr>) seleccionada.
 */
function handleRowSelectionAction(rowElement) {
    // 1. Deseleccionar todas las filas primero (limpiar estilos)
    document.querySelectorAll('.row-selector').forEach(el => {
        el.parentElement.classList.remove('selected');
    });

    // 2. Seleccionar la fila actual y añadir clase de estilo
    rowElement.classList.add('selected');

    // 3. Obtener el número de fila
    const rowNumber = rowElement.dataset.rowNumber || rowElement.querySelector('.row-selector').innerText.trim();
