 * Borra el contenido de todas las celdas de la fila actualmente seleccionada.
 * @param {HTMLElement} rowElement La fila (<tr>) que contiene los datos a limpiar.
 */
function deleteRowContent(rowElement) {
    const cellsToClear = rowElement.querySelectorAll('td[contenteditable="true"]');

    if (cellsToClear.length === 0) {
        console.log("No hay celdas editables para vaciar en esta fila.");
        return;
    }

    let clearedCount = 0;
    cellsToClear.forEach(cell => {
        // Limpiamos tanto el texto visible como el contenido HTML interno
        cell.innerText = ''; 
        cell.innerHTML = ''; 
        clearedCount++;
    });

    console.log(`Contenido de la fila limpiado exitosamente: ${clearedCount} celdas vaciadas.`);
}
