            const colLetter = colHeader.getAttribute('data-col-letter');
            if (!colLetter) {
                console.error("No se pudo determinar la letra de la columna.");
                return;
            }

            // Lógica original para borrar contenido (se mantiene, pero no es el foco del bug actual)
            const bodyRows = document.querySelector('tbody').querySelectorAll('tr');
            let clearedCount = 0;

            bodyRows.forEach(row => {
                const cellsInRow = row.querySelectorAll('td[contenteditable="true"]');
                const colIndex = colLetter.charCodeAt(0) - 'A'.charCodeAt(0);

                if (colIndex >= 0 && colIndex < cellsInRow.length) {
                    const cell = cellsInRow[colIndex];
                    cell.innerText = '';
                    cell.innerHTML = '';
                    clearedCount++;
                }
            });

            console.log(`Columna ${colLetter} vaciada exitosamente: ${clearedCount} celdas limpiadas.`);
        });
    });
}
```

### FUNCION: initializeRowSelection
```js
function initializeRowSelection() {
    // Usamos delegación de eventos en el cuerpo principal para manejar clics en cualquier <th> dentro de tbody.
    const tbody = document.querySelector('tbody');
    if (!tbody) return;

    tbody.addEventListener('click', function(e) {
        const targetTh = e.target.closest('th');
        if (!targetTh || !targetTh.parentNode.tagName === 'TR') return; // Asegura que estamos en un header de fila (el número)

        // 1. Lógica de selección/activo (mantenida)
        const rowElement = targetTh.parentNode;
        const allRows = tbody.querySelectorAll('tr');
        allRows.forEach(row => {
            row.classList.remove('selected-row');
        });

        if (!targetTh.closest('.hidden-row')) { // Si no está oculto, lo seleccionamos
             e.currentTarget.classList.add('selected-row');
        }


        // 2. Lógica para Ocultar/Mostrar Fila (R8)
        let isHidden = rowElement.hasAttribute('data-hidden') && targetTh.dataset.rowIndex;

        if (!isHidden) {
            hideRow(targetTh);
        } else {
            showRow(targetTh);
        }
    });
}
```

