### FUNCION: hideColumn
```js
function hideColumn(colIndex) {
    const colLetter = String.fromCharCode('A'.charCodeAt(0) + colIndex);

    // 1. Ocultar el encabezado de la columna en thead
    document.querySelectorAll('.col-header[data-col-letter="' + colLetter + '"]').forEach(el => {
        el.classList.add('hidden-col');
    });

    // 2. Ocultar todas las celdas (td) de esa columna en el tbody
    const bodyRows = document.querySelector('tbody').querySelectorAll('tr');
    bodyRows.forEach(row => {
        // Buscar la celda específica por índice (colIndex)
        const cellsInRow = row.querySelectorAll('td[contenteditable="true"]');
        if (cellsInRow.length > colIndex) {
            cellsInRow[colIndex].classList.add('hidden-col');
        }
    });

    // 3. Deshabilitar los controles de borrado/limpieza para esta columna, ya que está oculta
    const deleteButton = document.querySelector(`.delete-column-btn[data-col-letter="${colLetter}"]`);
    if (deleteButton) {
        deleteButton.disabled = true;
        deleteButton.style.opacity = 0.6;
    }

    console.log(`Columna ${colLetter} oculta exitosamente.`);
}
```

### FUNCION: unhideColumn
```js
function unhideColumn(colIndex) {
    const colLetter = String.fromCharCode('A'.charCodeAt(0) + colIndex);

    // 1. Mostrar el encabezado de la columna en thead
    document.querySelectorAll('.col-header[data-col-letter="' + colLetter + '"]').forEach(el => {
        el.classList.remove('hidden-col');
    });

    // 2. Mostrar todas las celdas (td) de esa columna en el tbody
    const bodyRows = document.querySelector('tbody').querySelectorAll('tr');
    bodyRows.forEach(row => {
        const cellsInRow = row.querySelectorAll('td[contenteditable="true"]');
        if (cellsInRow.length > colIndex) {
            cellsInRow[colIndex].classList.remove('hidden-col');
        }
    });

    // 3. Reactivar el control de borrado/limpieza para esta columna
    const deleteButton = document.querySelector(`.delete-column-btn[data-col-letter="${colLetter}"]`);
    if (deleteButton) {
        deleteButton.disabled = false;
        deleteButton.style.opacity = 1;
    }

    console.log(`Columna ${colLetter} visible nuevamente.`);
}
