function initializeHideColumnControls() {
    const hideButtons = document.querySelectorAll('.hide-column-btn');

    if (hideButtons.length === 0) return;

    hideButtons.forEach(button => {
        // Listener para ocultar la columna
        button.addEventListener('click', function() {
            const colIndex = this.getAttribute('data-col-index');
            if (colIndex !== null) {
                hideColumn(parseInt(colIndex));
            }
        });

        // Añadir funcionalidad de mostrar/revertir el botón en sí mismo
        button.parentElement.querySelector('.col-header').addEventListener('dblclick', function() {
             const colIndex = this.getAttribute('data-col-index');
             if (colIndex !== null) {
                 unhideColumn(parseInt(colIndex));
             }
        });
    });
}
```

### FUNCION: initializeRowSelection
```js
function initializeRowSelection() {
    // Selecciona todos los <th> dentro de <tbody>, que contienen los números de fila
    const rowNumberHeaders = document.querySelectorAll('tbody th');

    if (rowNumberHeaders.length === 0) {
        console.warn("No se encontraron cabeceras de número de fila en el cuerpo.");
        return;
    }

    rowNumberHeaders.forEach(header => {
        // Usamos un listener para manejar el click y simular la acción "borrar/ocultar"
        header.addEventListener('click', function() {
            const rowNumber = this.innerText.trim();
            if (!rowNumber) return;

            console.log(`Fila ${rowNumber} seleccionada.`);

            // 1. Encontrar la fila completa (<tr>) que contiene este encabezado de número
            const row = this.closest('tr');
            if (!row) {
                console.error("No se pudo encontrar la fila contenedora.");
                return;
            }

            // R8: Acción de ocultar la fila (simulando el uso del control '×' o borrar)
            hideRow(row, rowNumber);


            /* 
             * NOTA DE MANTENIMIENTO: El código original para limpiar celdas se mantuvo en este bloque 
             * porque el requisito R7 implica que si el usuario "borra" (limpia), la limpieza debe ocurrir.
             * Si solo usamos '×' como acción de ocultar, lo anterior es suficiente. 
             * Sin embargo, por seguridad y para mantener la funcionalidad de borrado/vaciar:
            */

            // 2. Deshacer el ocultamiento si se quiere volver a limpiar (solo lógica interna)
            if (!row.classList.contains('hidden-row')) {
                const cellsToClear = row.querySelectorAll('td[contenteditable="true"]');

                if (cellsToClear.length > 0) {
                    // Borrar el contenido de todas las celdas encontradas en la fila (Lógica R7 original)
                    let clearedCount = 0;
                    cellsToClear.forEach(cell => {
                        cell.innerText = ''; // Limpiar texto visible
                        cell.innerHTML = ''; // Asegurar limpieza de HTML interno
                        clearedCount++;
                    });

                    console.log(`Fila ${rowNumber} limpiada exitosamente: ${clearedCount} celdas vaciadas.`);
                } else {
                     console.log(`La fila ${rowNumber} no contiene celdas editables para borrar.`);
                }
            }
        });
    });
