/**
 * R1: Maneja el evento de cambio en las celdas editables.
 * Cuando un usuario escribe o pega contenido, esta función captura el valor 
 * y lo registra (simulando que se actualiza algún estado global).
 * @param {Event} event El evento de cambio ocurrido en el elemento.
 */
function handleCellChange(event) {
    const cell = event.target;
    const cellId = cell.getAttribute('data-cell');
    // Asegurarse que solo se tome texto visible y no contenido HTML si hay alguno pegado
    const newValue = (typeof cell.innerText !== 'undefined' ? cell.innerText : '').trim();

    if (cellId && newValue !== "") {
        console.log(`Celda ${cellId} actualizada: "${newValue}"`);
        // Aquí iría la lógica real para guardar o procesar el valor en un sistema de estado.
    } else if (cellId && newValue === "") {
         console.log(`Celda ${cellId} vacía.`);
    }
}

/**
 * Inicializa los listeners de eventos en todas las celdas del tablero.
 * Esto garantiza que cualquier interacción con una celda editable sea capturada.
 */
function initializeSheet() {
    // 1. Listener para celdas editables (R1)
    const cells = document.querySelectorAll('td[contenteditable="true"]');

    if (cells.length === 0) {
        console.warn("No se encontraron celdas editables en la hoja.");
        return;
    }

    cells.forEach(cell => {
        // Listener para captura inmediata durante la escritura
        cell.addEventListener('input', handleCellChange); 
        // Listener adicional al salir de la celda (mejor práctica)
        cell.addEventListener('blur', handleCellChange); 
    });

    console.log("Hoja de cálculo inicializada y lista para editar.");

    // 2. Inicializar controles de columna (R6 - Limpiar contenido, R8 - Ocultar/Mostrar Columna)
    initializeColumnControls();
    initializeHideColumnControls(); // Nuevo: Manejo de botones de ocultar/mostrar columnas

    // 3. Inicializar selección de filas (R7 - Borrar/Ocultar Fila)
    initializeRowSelection();
}


/**
 * Función principal que arranca la aplicación.
 */
function startApp() {
    // Se llama a la función de inicialización del tablero, incluyendo ahora los controles de columna y las filas.
    initializeSheet();
}

// --- Llamada de inicio de la aplicación ---
window.onload = startApp;

/**
 * Inicializa los listeners de eventos para la gestión de columnas (borrar/limpiar).
 * Asigna un manejador a cada botón de borrado de columna.
 */
function initializeColumnControls() {
    const deleteButtons = document.querySelectorAll('.delete-column-btn');

    if (deleteButtons.length === 0) return;

    deleteButtons.forEach(button => {
        // Asegurarse de que el botón tenga un listener, si se añade o modifica su estructura
        button.removeEventListener('click', handleColumnClear); // Limpiar listeners antiguos
    });

    // Reasociar todos los botones para asegurar la persistencia del listener
    deleteButtons.forEach(button => {
        button.addEventListener('click', handleColumnClear);
    });
}

/**
 * Maneja el evento de vaciado de una columna (Lógica R6).
 */
function handleColumnClear(e) {
    const button = e.currentTarget;
    e.stopPropagation(); 

    const colHeader = button.closest('.col-header');
    if (!colHeader) return;

    // Obtener la letra de la columna asociada (A, B, C...)
    const colLetter = colHeader.getAttribute('data-col-letter');
    if (!colLetter) {
        console.error("No se pudo determinar la letra de la columna.");
        return;
    }

    // 1. Seleccionar todas las celdas del cuerpo (tbody)
    const bodyRows = document.querySelector('tbody').querySelectorAll('tr');
    const columnCells = [];

    bodyRows.forEach(row => {
        // Las celdas de datos en una fila están en orden A, B, C...
        const cellsInRow = row.querySelectorAll('td[contenteditable="true"]');

        // Calcular el índice basado en la letra ('A' -> 0, 'B' -> 1, etc.)
        const colIndex = colLetter.charCodeAt(0) - 'A'.charCodeAt(0);

        if (colIndex >= 0 && colIndex < cellsInRow.length) {
            // Añadir la celda correspondiente a esta columna en esta fila
            columnCells.push(cellsInRow[colIndex]);
        }
    });

    // 2. Limpiar el contenido de todas las celdas encontradas para esa columna
    let clearedCount = 0;
    columnCells.forEach(cell => {
        cell.innerText = ''; // Borra el texto visible
        cell.innerHTML = ''; // Asegura que cualquier contenido HTML interno también se borre
        clearedCount++;
    });

    console.log(`Columna ${colLetter} vaciada exitosamente: ${clearedCount} celdas limpiadas.`);
}


/**
 * Inicializa los listeners de eventos para la selección y manejo de filas (R7).
 * Añade un manejador a los números de fila en el tbody.
 */
function initializeRowSelection() {
    // Selecciona todos los <th> dentro de <tbody>, que contienen los números de fila
    const rowNumberHeaders = document.querySelectorAll('tbody th');

    if (rowNumberHeaders.length === 0) {
        console.warn("No se encontraron cabeceras de número de fila en el cuerpo.");
        return;
    }

    rowNumberHeaders.forEach(header => {
        // Usamos un listener para manejar el click y simular la acción "borrar/ocultar"
        header.addEventListener('click', function() {
            const rowNumber = this.innerText.trim();
            if (!rowNumber) return;

            console.log(`Fila ${rowNumber} seleccionada.`);

            // 1. Encontrar la fila completa (<tr>) que contiene este encabezado de número
            const row = this.closest('tr');
            if (!row) {
                console.error("No se pudo encontrar la fila contenedora.");
                return;
            }

            // R8: Ocultar la fila (simulando el uso del control '×' o borrar)
            hideRow(row, rowNumber);

            /* 
             * Mantenemos la lógica de limpieza si no está oculta para cumplir con el requisito R7.
             */
            if (!row.classList.contains('hidden-row')) {
                // 2. Seleccionar todas las celdas de datos (td[contenteditable="true"]) en esa fila
                const cellsToClear = row.querySelectorAll('td[contenteditable="true"]');

                if (cellsToClear.length > 0) {
                    // 3. Borrar el contenido de todas las celdas encontradas en la fila
                    let clearedCount = 0;
                    cellsToClear.forEach(cell => {
                        cell.innerText = ''; // Limpiar texto visible
                        cell.innerHTML = ''; // Asegurar limpieza de HTML interno
                        clearedCount++;
                    });

                    console.log(`Fila ${rowNumber} limpiada exitosamente: ${clearedCount} celdas vaciadas.`);
                } else {
                     console.log(`La fila ${rowNumber} no contiene celdas editables para borrar.`);
                }
            }
        });
    });
}

// --- Funciones de Ocultar/Mostrar Columna (R8) ---

/**
 * Función auxiliar: Obtiene la letra de la columna a partir del índice.
 */
function getColLetter(index) {
    return String.fromCharCode('A'.charCodeAt(0) + index);
}


/**
 * Oculta completamente una columna en el tablero (header y todas las celdas).
 * @param {number} colIndex Índice de la columna (0 = A, 1 = B...).
 */
function hideColumn(colIndex) {
    const colLetter = getColLetter(colIndex);

    // 1. Ocultar el encabezado de la columna en thead
    document.querySelectorAll('.col-header[data-col-letter="' + colLetter + '"]').forEach(el => {
        el.classList.add('hidden-col');
    });

    // 2. Ocultar todas las celdas (td) de esa columna en el tbody
    const bodyRows = document.querySelector('tbody').querySelectorAll('tr');
    bodyRows.forEach(row => {
        // Buscar la celda específica por índice (colIndex)
        const cellsInRow = row.querySelectorAll('td[contenteditable="true"]');
        if (cellsInRow.length > colIndex) {
            cellsInRow[colIndex].classList.add('hidden-col');
        }
    });

    // 3. Deshabilitar el botón de borrado/limpieza para esta columna, ya que está oculta
    const deleteButton = document.querySelector(`.delete-column-btn[data-col-letter="${colLetter}"]`);
    if (deleteButton) {
        deleteButton.disabled = true;
        deleteButton.style.opacity = 0.6;
    }

    console.log(`Columna ${colLetter} oculta exitosamente.`);
}


/**
 * Muestra completamente una columna en el tablero.
 * @param {number} colIndex Índice de la columna (0 = A, 1 = B...).
 */
function unhideColumn(colIndex) {
    const colLetter = getColLetter(colIndex);

    // 1. Mostrar el encabezado de la columna en thead
    document.querySelectorAll('.col-header[data-col-letter="' + colLetter + '"]').forEach(el => {
        el.classList.remove('hidden-col');
    });

    // 2. Mostrar todas las celdas (td) de esa columna en el tbody
    const bodyRows = document.querySelector('tbody').querySelectorAll('tr');
    bodyRows.forEach(row => {
        const cellsInRow = row.querySelectorAll('td[contenteditable="true"]');
        if (cellsInRow.length > colIndex) {
            cellsInRow[colIndex].classList.remove('hidden-col');
        }
    });

    // 3. Reactivar el botón de borrado/limpieza para esta columna
    const deleteButton = document.querySelector(`.delete-column-btn[data-col-letter="${colLetter}"]`);
    if (deleteButton) {
        deleteButton.disabled = false;
        deleteButton.style.opacity = 1;
    }

    console.log(`Columna ${colLetter} visible nuevamente.`);
}


/**
 * Oculta completamente una fila en el tablero (incluyendo th del número de fila y todos los td).
 * @param {HTMLElement} rowElement Elemento tr de la fila a ocultar.
 * @param {string} rowNumber Número de la fila.
 */
function hideRow(rowElement, rowNumber) {
    // Oculta la fila completa (incluyendo th del número de fila y todos los td)
    if (rowElement) {
        rowElement.classList.add('hidden-row');
    }

    console.log(`Fila ${rowNumber} oculta exitosamente.`);
}


/**
 * Inicializa los listeners para los nuevos botones de ocultar columna en thead.
 */
function initializeHideColumnControls() {
    const hideButtons = document.querySelectorAll('.hide-column-btn');

    if (hideButtons.length === 0) return;

    hideButtons.forEach(button => {
        // Listener para ocultar la columna al hacer click en el botón
        button.addEventListener('click', function() {
            const colIndex = this.getAttribute('data-col-index');
            if (colIndex !== null) {
                hideColumn(parseInt(colIndex));
            }
        });

        // Añadir funcionalidad de mostrar/revertir el botón al hacer doble click en el header
        button.parentElement.addEventListener('dblclick', function() {
             const colIndex = this.getAttribute('data-col-index');
             if (colIndex !== null) {
                 unhideColumn(parseInt(colIndex));
             }
        });
    });
}
