function handleColumnControlClick(e) {
    const button = e.target;
    if (!button || !button.classList.contains('hide-column-btn')) return;

    // Prevenir que el evento se propague y active otros listeners si no es necesario
    e.preventDefault(); 

    const colIndex = button.dataset.colIndex;
    const colLetter = button.dataset.colLetter;

    if (!colIndex || !colLetter) {
        console.error("Falta data-col-index o data-col-letter para el control de columna.");
        return;
    }

    // 1. Ocultar la cabecera de la columna (A, B, C...) en thead
    const columnHeader = document.querySelector(`.col-header[data-col-index="${colIndex}"]`);
    if (columnHeader) {
        columnHeader.style.display = 'none';
    }

    // 2. Ocultar todos los botones de control asociados a esa columna en thead
    const headerControls = document.querySelectorAll(`.col-header[data-col-index="${colIndex}"] button`);
    headerControls.forEach(btn => {
        btn.style.display = 'none';
    });

    // 3. Ocultar todas las celdas (td) de la columna en tbody
    const allCellsInColumn = document.querySelectorAll(`[data-cell^="${colLetter}"]:not([data-cell*="1"])`); // Excluir A1, B1, etc., si hay alguna excepción lógica. Aquí buscamos todas las celdas que empiezan con la letra.
    allCellsInColumn.forEach(cell => {
        // Para asegurar que se oculte el contenido y su contenedor
        cell.style.display = 'none'; 
    });

    console.log(`Columna ${colLetter} (${colIndex}) oculta exitosamente.`);
}
