```javascript
/**
 * Inicializa los listeners de eventos para la gestión de columnas (ocultar/mostrar).
 * Asigna un manejador a cada botón de ocultar columna.
 */
function initializeColumnControls() {
    const deleteButtons = document.querySelectorAll('.delete-column-btn');

    if (deleteButtons.length === 0) return;

    deleteButtons.forEach(button => {
        button.addEventListener('click', function(e) {
            e.stopPropagation(); // Detiene la propagación del evento para evitar disparadores innecesarios en el contenedor padre

            const colHeader = this.closest('.col-header');
            if (!colHeader) return;

            // Obtener la letra de la columna asociada (A, B, C...)
            const colLetter = colHeader.getAttribute('data-col-letter');
            if (!colLetter) {
                console.error("No se pudo determinar la letra de la columna.");
                return;
            }

            // 1. Recolectar todos los elementos que deben ocultarse (Encabezado + Celdas de datos)
            let elementsToHide = [];

            // A) Buscar y añadir el encabezado de columna en THEAD
            const theadHeader = document.querySelector('thead th[data-col-letter="' + colLetter + '"]');
            if (theadHeader) {
                elementsToHide.push(theadHeader);
            }

            // B) Buscar y añadir todas las celdas de datos en TBODY
            const bodyRows = document.querySelector('tbody').querySelectorAll('tr');
            bodyRows.forEach(row => {
                const cellsInRow = row.querySelectorAll('td[contenteditable="true"]');

                // Calcular el índice basado en la letra ('A' -> 0, 'B' -> 1, etc.)
                const colIndex = colLetter.charCodeAt(0) - 'A'.charCodeAt(0);

                if (colIndex >= 0 && colIndex < cellsInRow.length) {
                    // Añadir la celda de datos correspondiente a esta columna en esta fila
                    elementsToHide.push(cellsInRow[colIndex]);
                }
            });

            // 2. Ocultar todos los elementos encontrados aplicando style.display = 'none'
            elementsToHide.forEach(element => {
                element.style.display = 'none';
            });

            console.log(`Columna ${colLetter} oculta exitosamente.`);
        });
    });
}
