### FUNCION: handleCellChange
```javascript
function handleCellChange(event) {
    const cell = event.target;
    const cellId = cell.getAttribute('data-cell');
    let rawInput = cell.innerText.trim();

    if (!cellId) return;

    // 1. Check if the input is a formula (starts with '=')
    if (rawInput && rawInput.startsWith("=")) {
        const formulaString = rawInput.substring(1).toUpperCase().trim();

        // Attempt to calculate the result based on current sheet state
        let calculatedResult = calculateFormula(formulaString);

        if (calculatedResult !== null) {
            // Display the calculated result in the cell
            cell.innerText = calculatedResult; 
            // Save the numerical/final result, not the formula string itself
            localStorage.setItem(cellId, calculatedResult);
            console.log(`Celda ${cellId} calculada: "${calculatedResult}"`);
        } else {
            // If calculation fails or is unsupported, treat it as raw text input
            const newValue = rawInput;
             if (newValue !== "") {
                console.log(`Celda ${cellId} actualizada con fórmula no resuelta: "${newValue}"`);
                localStorage.setItem(cellId, newValue);
            } else {
                 console.log(`Celda ${cellId} vacía.`);
                 localStorage.removeItem(cellId);
            }
        }
    } 
    // 2. Handle normal input (text/number)
    else {
        const newValue = rawInput;

        if (newValue !== "") {
            console.log(`Celda ${cellId} actualizada: "${newValue}"`);
            localStorage.setItem(cellId, newValue);
        } else {
             console.log(`Celda ${cellId} vacía.`);
             // Eliminar la clave de localStorage si el usuario borra todo
             localStorage.removeItem(cellId);
        }
    }
}
