### FUNCION: calculateFormula
```javascript
/**
 * Intenta evaluar una fórmula simple (actualmente solo SUMA) basándose en los valores 
 * almacenados en LocalStorage de las celdas referenciadas.
 * @param {string} formulaString La cadena de la fórmula sin el signo '='.
 * @returns {string | null} El resultado calculado como string, o null si falla.
 */
function calculateFormula(formulaString) {
    // Regex simple para capturar argumentos dentro de SUMA(...)
    const sumRegex = /SUMA\(([^)]+)\)/i; 
    const match = formulaString.match(sumRegex);

    if (!match) return null;

    let argsString = match[1];
    // Normalizar separadores (coma o punto y coma) a un espacio para facilitar el split
    argsString = argsString.replace(/[,;]/g, ' ').trim(); 
    const cellRefs = argsString.split(/\s+/).filter(ref => ref);

    let sum = 0;
    for (const ref of cellRefs) {
        // Regex para extraer la referencia de celda (Ej: A1, B1)
        const cellMatch = ref.match(/([A-Z]+\d+)/i); 
        if (!cellMatch) continue;

        const targetCellId = cellMatch[0];

        // Obtener el valor actual del estado de la hoja (localStorage simula esto)
        let valueStr = localStorage.getItem(targetCellId);

        // Intentar parsear como flotante, si no se puede, asumir 0 para evitar NaN
        const value = parseFloat(valueStr) || 0; 
        sum += value;
    }

    // Devolver el resultado formateado como string (ej: "11")
    return sum.toString(); 
}
```

